const bouton = document.querySelector("#charger");
const etat = document.querySelector("#etat");
const liste = document.querySelector("#liste-notes");

bouton.addEventListener("click", async () => {
  etat.textContent = "Chargement…";
  try {
    const response = await fetch("http://localhost:3000/api/notes");
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const resultat = await response.json();
    liste.innerHTML = resultat.donnees.map((note) => `<li>${note.titre}</li>`).join("");
    etat.textContent = `${resultat.donnees.length} note(s)`;
  } catch (erreur) {
    etat.textContent = `Impossible de charger : ${erreur.message}`;
  }
});
